prices.expect_price()
    .with(mockall::predicate::eq("A-1"))
    .returning(|_| Ok(Money::cents(999)));
let checkout = Checkout::new(prices);

use wiremock::{MockServer, Mock, ResponseTemplate};
use wiremock::matchers::{method, path};

let server = MockServer::start().await;
Mock::given(method("GET")).and(path("/price/A-1"))
    .respond_with(ResponseTemplate::new(200).set_body_json(serde_json::json!({"price": 9.99})))
    .mount(&server).await;
let client = PricesClient::new(server.uri());
